def contains_nearby_almost_duplicate_brute(nums, index_diff, value_diff):
    n = len(nums)
    for i in range(n):
        for j in range(i + 1, min(i + index_diff + 1, n)):        # only check nearby indices
            if abs(nums[i] - nums[j]) <= value_diff:
                return True
    return False

