def contains_nearby_almost_duplicate(nums, index_diff, value_diff):
    buckets = {}
    w = value_diff + 1
    def bucket_id(x):
        return x // w if x >= 0 else (x + 1) // w - 1
    for i, x in enumerate(nums):
        bid = bucket_id(x)
        if bid in buckets:
            return True                                       # same bucket, automatic match
        if bid - 1 in buckets and abs(x - buckets[bid - 1]) <= value_diff:
            return True                                       # adjacent bucket check
        if bid + 1 in buckets and abs(x - buckets[bid + 1]) <= value_diff:
            return True
        buckets[bid] = x
        if i >= index_diff:
            del buckets[bucket_id(nums[i - index_diff])]        # slide the window
    return False

