import java.util.*;

public class Main {
    static long bucketId(long x, long w) {
        return x >= 0 ? x / w : (x + 1) / w - 1;
    }
    static boolean containsNearbyAlmostDuplicate(int[] nums, int indexDiff, int valueDiff) {
        Map<Long, Long> buckets = new HashMap<>();
        long w = (long) valueDiff + 1;
        for (int i = 0; i < nums.length; i++) {
            long bid = bucketId(nums[i], w);
            if (buckets.containsKey(bid)) return true;                    // automatic match
            if (buckets.containsKey(bid - 1) && Math.abs(nums[i] - buckets.get(bid - 1)) <= valueDiff) return true;
            if (buckets.containsKey(bid + 1) && Math.abs(nums[i] - buckets.get(bid + 1)) <= valueDiff) return true;
            buckets.put(bid, (long) nums[i]);
            if (i >= indexDiff) buckets.remove(bucketId(nums[i - indexDiff], w));    // slide the window
        }
        return false;
    }
}

