#include <bits/stdc++.h>
using namespace std;

long long bucketId(long long x, long long w) {
    return x >= 0 ? x / w : (x + 1) / w - 1;
}

bool containsNearbyAlmostDuplicate(vector<int>& nums, int indexDiff, int valueDiff) {
    unordered_map<long long, long long> buckets;
    long long w = (long long)valueDiff + 1;
    for (int i = 0; i < (int)nums.size(); i++) {
        long long bid = bucketId(nums[i], w);
        if (buckets.count(bid)) return true;                                  // automatic match
        if (buckets.count(bid - 1) && abs(nums[i] - buckets[bid - 1]) <= valueDiff) return true;
        if (buckets.count(bid + 1) && abs(nums[i] - buckets[bid + 1]) <= valueDiff) return true;
        buckets[bid] = nums[i];
        if (i >= indexDiff) buckets.erase(bucketId(nums[i - indexDiff], w));       // slide the window
    }
    return false;
}
